import React, { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import { apiRequest } from "../services/auth";

const Dashboard = () => {
  const navigate = useNavigate();
  const [activeSection, setActiveSection] = useState("accueil");
  const [selectedEntreprise, setSelectedEntreprise] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [showAddEntrepriseModal, setShowAddEntrepriseData] = useState(false);
  const [selectedDocument, setSelectedDocument] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [addEntrepriseData, setAddEntrepriseData] = useState({
    nom: "",
    siret: "",
    telephone: "",
    email: "",
    nomRepresentant: "",
    prenomRepresentant: "",
    domainesActivite: [],
    secteurActivite: "",
  });
  const [profileData, setProfileData] = useState({
    nom: "Logo service",
    siret: "12345678901234",
    adresse: "Ouagadougou 01 BP 824",
    email: "contact@techbat.fr",
    telephone: "0123456789",
    nomRepresentant: "Rayaissse ",
    prenomRepresentant: "Jude",
    secteurActivite: "Develloppement",
  });
  const [filters, setFilters] = useState({
    domaine: "",
    dateDebut: "",
    dateFin: "",
  });

  // NOUVEAUX ÉTATS POUR LES PUBLICATIONS
  const [publications, setPublications] = useState([]);
  const [loadingPublications, setLoadingPublications] = useState(false);
  const [errorPublications, setErrorPublications] = useState(null);

  // Fonction de déconnexion
  const handleLogout = () => {
    localStorage.removeItem("accessToken");
    localStorage.removeItem("refreshToken");
    sessionStorage.removeItem("accessToken");
    sessionStorage.removeItem("refreshToken");
    navigate("/Connexion");
  };

  // NOUVEAU useEffect POUR CHARGER LES PUBLICATIONS
  useEffect(() => {
    const fetchPublications = async () => {
      setLoadingPublications(true);
      setErrorPublications(null); // Réinitialiser l'erreur

      try {
        const response = await apiRequest(
          "http://192.168.1.69:8000/api/backend/api/publications/"
        );

        if (!response) {
          setErrorPublications(
            new Error(
              "Votre session a expiré ou la requête a échoué. Veuillez vous reconnecter."
            )
          );
          return;
        }

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(
            `Erreur HTTP lors de la récupération des publications: ${
              response.status
            } - ${JSON.stringify(errorData)}`
          );
        } else {
          const data = await response.json();
          console.log("Données de publications reçues:", data); // Pour vérifier ce que vous recevez
          setPublications(data); // Mettre à jour l'état avec les publications reçues
        }
      } catch (error) {
        setErrorPublications(error); // Stocker l'erreur pour l'affichage
        console.error(
          "Erreur lors de la récupération des publications:",
          error
        );
      } finally {
        setLoadingPublications(false); // Arrêter l'état de chargement
      }
    };

    if (activeSection === "veille") {
      fetchPublications();
    }
  }, [activeSection, navigate]);

  // Fonction pour gérer le clic sur "Voir document" ou "Détails"
  const handleViewDocument = (document) => {
    setSelectedDocument(document);
    setShowModal(true);
  };

  const handleFilterChange = (e) => {
    const { name, value } = e.target;
    setFilters((prevFilters) => ({
      ...prevFilters,
      [name]: value,
    }));
  };

  const handleSidebarToggle = () => {
    setSidebarOpen(!sidebarOpen);
  };

  const handleEntrepriseChange = (e) => {
    setSelectedEntreprise(e.target.value);
  };

  const handleAddEntrepriseChange = (e) => {
    const { name, value } = e.target;
    setAddEntrepriseData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  const handleDomaineChange = (e) => {
    const { value, checked } = e.target;
    setAddEntrepriseData((prevData) => {
      const newDomaines = checked
        ? [...prevData.domainesActivite, value]
        : prevData.domainesActivite.filter((domaine) => domaine !== value);
      return { ...prevData, domainesActivite: newDomaines };
    });
  };

  const handleAddEntrepriseSubmit = (e) => {
    e.preventDefault();
    console.log("Nouvelle entreprise:", addEntrepriseData);
    setShowAddEntrepriseData(false);
  };

  const renderAccueil = () => (
    <div className="dashboard-content-section">
      <h2>Bienvenue sur votre tableau de bord !</h2>
      <p>
        Accédez rapidement aux informations essentielles, aux alertes et à votre
        veille personnalisée.
      </p>
      <div className="stats-cards row">
        <div className="col-md-4">
          <div className="card text-center">
            <div className="card-body">
              <h5 className="card-title">Publications Récentes</h5>
              <p className="card-text">50</p>
            </div>
          </div>
        </div>
        <div className="col-md-4">
          <div className="card text-center">
            <div className="card-body">
              <h5 className="card-title">Alertes Actives</h5>
              <p className="card-text">5</p>
            </div>
          </div>
        </div>
        <div className="col-md-4">
          <div className="card text-center">
            <div className="card-body">
              <h5 className="card-title">Entreprises Suivies</h5>
              <p className="card-text">10</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderVeille = () => {
    return (
      <div className="dashboard-content-section">
        <h2>Veille Technologique et Marchés</h2>
        <p>Consultez les dernières publications de veille.</p>

        {/* Section de filtres - Gardons les classes Bootstrap ici pour le formulaire */}
        <div className="filters-section mb-4 p-3 border rounded">
          <h4 className="mb-3">Filtrer les publications</h4>
          <div className="row g-3">
            <div className="col-md-4">
              <label htmlFor="domaine" className="form-label">
                Domaine d'activité
              </label>
              <select
                className="form-select"
                id="domaine"
                name="domaine"
                value={filters.domaine}
                onChange={handleFilterChange}
              >
                <option value="">Tous les domaines</option>
                <option value="IT">Technologies de l'Information</option>
                <option value="Finance">Finance</option>
                <option value="Energie">Énergie</option>
                <option value="Sante">Santé</option>
                {/* Ajoutez d'autres options de domaine */}
              </select>
            </div>
            <div className="col-md-4">
              <label htmlFor="dateDebut" className="form-label">
                Date de début
              </label>
              <input
                type="date"
                className="form-control"
                id="dateDebut"
                name="dateDebut"
                value={filters.dateDebut}
                onChange={handleFilterChange}
              />
            </div>
            <div className="col-md-4">
              <label htmlFor="dateFin" className="form-label">
                Date de fin
              </label>
              <input
                type="date"
                className="form-control"
                id="dateFin"
                name="dateFin"
                value={filters.dateFin}
                onChange={handleFilterChange}
              />
            </div>
          </div>
        </div>

        {/* Affichage des messages de chargement/erreur */}
        {loadingPublications && (
          <div className="text-center mt-3">
            <div className="spinner-border text-primary" role="status">
              <span className="visually-hidden">Chargement...</span>
            </div>
          </div>
        )}
        {errorPublications && (
          <div className="alert alert-danger mt-3">
            Erreur: {errorPublications.message}
          </div>
        )}

        {/* Tableau des publications */}
        {/* J'ai remis les classes Bootstrap d'origine pour le tableau, en supposant qu'elles fonctionnaient avant */}
        {!loadingPublications &&
          !errorPublications &&
          publications.length === 0 && (
            <p className="mt-3 text-center">
              Aucune publication trouvée pour le moment.
            </p>
          )}

        {!loadingPublications &&
          !errorPublications &&
          publications.length > 0 && (
            <div className="table-responsive mt-4">
              <table className="table table-hover table-striped">
                {" "}
                {/* Classes Bootstrap originales */}
                <thead>
                  <tr>
                    <th>Titre</th>
                    <th>Numéro</th> {/* Ajouté basé sur les données API */}
                    <th>Date</th>
                    <th>Source</th>
                    <th>Type</th> {/* Ajouté basé sur les données API */}
                    <th>Domaines</th> {/* Ajouté basé sur les données API */}
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {publications.map((publication) => (
                    <tr key={publication.id}>
                      <td>{publication.titre}</td>
                      <td>{publication.numero}</td> {/* Champ 'numero' */}
                      <td>
                        {new Date(
                          publication.date_publication
                        ).toLocaleDateString()}
                      </td>
                      <td>{publication.source}</td>
                      <td>{publication.type_publication}</td>{" "}
                      {/* Champ 'type_publication' */}
                      <td>
                        {/* Affichage des domaines, joignez les libellés avec une virgule */}
                        {publication.domaines &&
                          publication.domaines.map((d) => d.libelle).join(", ")}
                      </td>
                      <td>
                        <button
                          className="btn btn-sm btn-info"
                          onClick={() => handleViewDocument(publication)}
                        >
                          Détails
                        </button>
                        {/* Si vous avez un lien direct vers le document via l'API, vous pouvez l'ajouter ici */}
                        {/* {publication.lien_document && (
                        <a href={publication.lien_document} target="_blank" rel="noopener noreferrer" className="btn btn-sm btn-outline-primary ms-2">
                          Voir PDF
                        </a>
                      )} */}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
      </div>
    );
  };

  const renderAlertes = () => (
    <div className="dashboard-content-section">
      <h2>Alertes personnalisées</h2>
      <p>Configurez et consultez vos alertes ici.</p>
      <p>Fonctionnalité en cours de développement.</p>
    </div>
  );

  const renderProfil = () => (
    <div className="dashboard-content-section">
      <h2>Mon Profil Entreprise</h2>
      <p>Gérez les informations de votre entreprise.</p>
      <div className="card profile-card p-4">
        <div className="mb-3">
          <strong>Nom de l'entreprise:</strong> {profileData.nom}
        </div>
        <div className="mb-3">
          <strong>SIRET:</strong> {profileData.siret}
        </div>
        <div className="mb-3">
          <strong>Adresse:</strong> {profileData.adresse}
        </div>
        <div className="mb-3">
          <strong>Email:</strong> {profileData.email}
        </div>
        <div className="mb-3">
          <strong>Téléphone:</strong> {profileData.telephone}
        </div>
        <div className="mb-3">
          <strong>Représentant:</strong>{" "}
          {profileData.nomRepresentant + " " + profileData.prenomRepresentant}
        </div>
        <div className="mb-3">
          <strong>Secteur d'activité:</strong> {profileData.secteurActivite}
        </div>
        <button className="btn btn-primary">Modifier le profil</button>
      </div>
      <h3 className="mt-4">Entreprises Suivies</h3>
      <p>Liste des entreprises pour lesquelles vous recevez des veilles.</p>
      <div className="d-flex justify-content-between align-items-center mb-3">
        <select
          className="form-select w-auto"
          value={selectedEntreprise}
          onChange={handleEntrepriseChange}
        >
          <option value="">Sélectionner une entreprise</option>
          <option value="entreprise1">Entreprise A</option>
          <option value="entreprise2">Entreprise B</option>
        </select>
        <button
          className="btn btn-success"
          onClick={() => setShowAddEntrepriseData(true)}
        >
          Ajouter une entreprise
        </button>
      </div>

      {/* Modal pour Ajouter une entreprise */}
      {showAddEntrepriseModal && (
        <div className="modal show d-block" tabIndex="-1">
          <div className="modal-dialog">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Ajouter une Nouvelle Entreprise</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowAddEntrepriseData(false)}
                ></button>
              </div>
              <div className="modal-body">
                <form onSubmit={handleAddEntrepriseSubmit}>
                  <div className="mb-3">
                    <label htmlFor="nomEntreprise" className="form-label">
                      Nom de l'entreprise
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      id="nomEntreprise"
                      name="nom"
                      value={addEntrepriseData.nom}
                      onChange={handleAddEntrepriseChange}
                      required
                    />
                  </div>
                  <div className="mb-3">
                    <label htmlFor="siretEntreprise" className="form-label">
                      SIRET
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      id="siretEntreprise"
                      name="siret"
                      value={addEntrepriseData.siret}
                      onChange={handleAddEntrepriseChange}
                      required
                    />
                  </div>
                  <div className="mb-3">
                    <label htmlFor="telEntreprise" className="form-label">
                      Téléphone
                    </label>
                    <input
                      type="tel"
                      className="form-control"
                      id="telEntreprise"
                      name="telephone"
                      value={addEntrepriseData.telephone}
                      onChange={handleAddEntrepriseChange}
                    />
                  </div>
                  <div className="mb-3">
                    <label htmlFor="emailEntreprise" className="form-label">
                      Email
                    </label>
                    <input
                      type="email"
                      className="form-control"
                      id="emailEntreprise"
                      name="email"
                      value={addEntrepriseData.email}
                      onChange={handleAddEntrepriseChange}
                      required
                    />
                  </div>
                  <div className="mb-3">
                    <label
                      htmlFor="nomRepresentantEntreprise"
                      className="form-label"
                    >
                      Nom du représentant
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      id="nomRepresentantEntreprise"
                      name="nomRepresentant"
                      value={addEntrepriseData.nomRepresentant}
                      onChange={handleAddEntrepriseChange}
                    />
                  </div>
                  <div className="mb-3">
                    <label
                      htmlFor="prenomRepresentantEntreprise"
                      className="form-label"
                    >
                      Prénom du représentant
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      id="prenomRepresentantEntreprise"
                      name="prenomRepresentant"
                      value={addEntrepriseData.prenomRepresentant}
                      onChange={handleAddEntrepriseChange}
                    />
                  </div>
                  <div className="mb-3">
                    <label className="form-label">Domaines d'activité</label>
                    <div>
                      <div className="form-check form-check-inline">
                        <input
                          className="form-check-input"
                          type="checkbox"
                          id="domaineIT"
                          name="domaine"
                          value="IT"
                          checked={addEntrepriseData.domainesActivite.includes(
                            "IT"
                          )}
                          onChange={handleDomaineChange}
                        />
                        <label className="form-check-label" htmlFor="domaineIT">
                          Technologies de l'Information
                        </label>
                      </div>
                      <div className="form-check form-check-inline">
                        <input
                          className="form-check-input"
                          type="checkbox"
                          id="domaineFinance"
                          name="domaine"
                          value="Finance"
                          checked={addEntrepriseData.domainesActivite.includes(
                            "Finance"
                          )}
                          onChange={handleDomaineChange}
                        />
                        <label
                          className="form-check-label"
                          htmlFor="domaineFinance"
                        >
                          Finance
                        </label>
                      </div>
                    </div>
                  </div>
                  <div className="mb-3">
                    <label htmlFor="secteurActivite" className="form-label">
                      Secteur d'activité
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      id="secteurActivite"
                      name="secteurActivite"
                      value={addEntrepriseData.secteurActivite}
                      onChange={handleAddEntrepriseChange}
                    />
                  </div>
                  <div className="d-flex justify-content-end">
                    <button
                      type="button"
                      className="btn btn-secondary me-2"
                      onClick={() => setShowAddEntrepriseData(false)}
                    >
                      Annuler
                    </button>
                    <button type="submit" className="btn btn-primary">
                      Ajouter
                    </button>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );

  const renderContent = () => {
    switch (activeSection) {
      case "accueil":
        return renderAccueil();
      case "veille":
        return renderVeille();
      case "alertes":
        return renderAlertes();
      case "profil":
        return renderProfil();
      default:
        return renderAccueil();
    }
  };

  return (
    <div className={`dashboard-container ${sidebarOpen ? "sidebar-open" : ""}`}>
      {/* Sidebar */}
      <aside className={`dashboard-sidebar ${sidebarOpen ? "open" : ""}`}>
        <div className="sidebar-header">
          <img
            src="/path/to/your/logo.png"
            alt="Logo"
            className="sidebar-logo"
          />
          <h3>E-Assis</h3>
          <button className="toggle-btn" onClick={handleSidebarToggle}>
            <i className="bi bi-x-lg"></i>
          </button>
        </div>
        <nav className="sidebar-nav">
          <ul>
            <li>
              <button
                className={`nav-button ${
                  activeSection === "accueil" ? "active" : ""
                }`}
                onClick={() => setActiveSection("accueil")}
              >
                <i className="bi bi-house-door me-2"></i> Accueil
              </button>
            </li>
            <li>
              <button
                className={`nav-button ${
                  activeSection === "veille" ? "active" : ""
                }`}
                onClick={() => setActiveSection("veille")}
              >
                <i className="bi bi-eye me-2"></i> Veille
              </button>
            </li>
            <li>
              <button
                className={`nav-button ${
                  activeSection === "alertes" ? "active" : ""
                }`}
                onClick={() => setActiveSection("alertes")}
              >
                <i className="bi bi-bell me-2"></i> Alertes
              </button>
            </li>
            <li>
              <button
                className={`nav-button ${
                  activeSection === "profil" ? "active" : ""
                }`}
                onClick={() => setActiveSection("profil")}
              >
                <i className="bi bi-person me-2"></i> Profil
              </button>
            </li>
            <li>
              <button
                className="nav-button logout-button"
                onClick={handleLogout}
              >
                <i className="bi bi-box-arrow-right me-2"></i> Déconnexion
              </button>
            </li>
          </ul>
        </nav>
      </aside>

      {/* Main Content */}
      <main className="dashboard-main-content">
        <header className="dashboard-header">
          <button className="toggle-btn-top" onClick={handleSidebarToggle}>
            <i className="bi bi-list"></i>
          </button>
          <h1>Tableau de Bord</h1>
          <div className="header-actions">
            <input
              type="text"
              placeholder="Rechercher..."
              className="form-control search-input"
            />
            <button className="btn btn-secondary ms-2">
              <i className="bi bi-search"></i>
            </button>
            <button className="btn btn-notification ms-2">
              <i className="bi bi-bell"></i>
              <span className="badge bg-danger">3</span>
            </button>
            <div className="user-info ms-3">
              <span>Adrien D.</span>
              <img
                src="/path/to/user-avatar.png"
                alt="Avatar"
                className="user-avatar"
              />
            </div>
          </div>
        </header>

        {renderContent()}
      </main>

      {/* Document Detail Modal */}
      {showModal && (
        <div className="modal show d-block" tabIndex="-1">
          <div className="modal-dialog modal-dialog-centered modal-lg">
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">Détails du Document</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowModal(false)}
                ></button>
              </div>
              <div className="modal-body">
                {selectedDocument && (
                  <div className="document-details">
                    <h6>Titre: {selectedDocument.titre}</h6>
                    <p>
                      <strong>Numéro:</strong> {selectedDocument.numero}
                    </p>
                    <p>
                      <strong>Date:</strong>{" "}
                      {new Date(
                        selectedDocument.date_publication
                      ).toLocaleDateString()}
                    </p>
                    <p>
                      <strong>Source:</strong> {selectedDocument.source}
                    </p>
                    <p>
                      <strong>Type:</strong> {selectedDocument.type_publication}
                    </p>
                    <p>
                      <strong>Domaines:</strong>{" "}
                      {selectedDocument.domaines &&
                        selectedDocument.domaines
                          .map((d) => d.libelle)
                          .join(", ")}
                    </p>
                    {/* Placeholder for PDF viewer or link */}
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="60"
                      height="60"
                      fill="currentColor"
                      className="bi bi-file-earmark-pdf"
                      viewBox="0 0 16 16"
                    >
                      <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5L14 4.5zM9.5 3A1.5 1.5 0 0 0 11 4.5h2V14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1h5.5v2z" />
                    </svg>
                    <p>Aperçu du document PDF</p>
                  </div>
                )}
              </div>
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={() => setShowModal(false)}
                >
                  Fermer
                </button>
                <button type="button" className="btn btn-cta">
                  Télécharger
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;
